// Airport data: bundled static columnar JSON, public/data/airports.json, served
// same-origin. Generated by `npm run data:airports` (scripts/build-airports.mjs)
// from OurAirports airports.csv pinned to davidmegginson/ourairports-data commit
// 64af12951161ed52bc733eb4101224643c48850a; see public/data/airports.meta.json.
// OurAirports data is public domain (https://ourairports.com/data/).
export const AIRPORTS_DATA_URL = '/data/airports.json'

// Sea ports: bundled static GeoJSON asset (NGA World Port Index, public domain)
export const WORLD_PORTS_URL = '/data/ports.geojson'

export const LAYERS = {
  AIRPORTS: { id: 'airports', label: 'Airports' },
  PORTS:    { id: 'ports',    label: 'Sea Ports' },
  HEATMAP:  { id: 'heatmap',  label: 'Heatmap' },
}

// Free dark vector basemap - no API key required.
export const BASEMAP_STYLE = 'https://basemaps.cartocdn.com/gl/dark-matter-gl-style/style.json'

// Default map center - global view
export const DEFAULT_VIEW = {
  longitude: 0,
  latitude: 20,
  zoom: 2,
}